DO $links$
DECLARE target record;
BEGIN
 FOR target IN SELECT g.key, t.id, t.slug FROM player_guides g JOIN threads t ON t.id = g.thread_id WHERE g.locale = 'pt-BR' LOOP
  UPDATE posts SET body_md = replace(body_md, '/community/guide-placeholder/' || target.key, '/pt-BR/community/t/' || target.id || '/' || target.slug),
   body_html = replace(body_html, '/community/guide-placeholder/' || target.key, '/pt-BR/community/t/' || target.id || '/' || target.slug)
  WHERE number = 1 AND thread_id IN (SELECT thread_id FROM player_guides WHERE locale = 'pt-BR');
 END LOOP;
END $links$;
